// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: a real, non-zero depositor with a positive deposit
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, c.MinDeposit() + 1, uint256(100 ether));
        vm.deal(actor, amount);

        // Deposit the full amount so the depositor's balance is exactly `amount`
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 balBefore = c.balances(actor);
        vm.assume(balBefore > 0);

        // Withdraw exactly the full balance: reference succeeds and zeroes it;
        // the bug's strict inequality silently reverts (no state change).
        vm.prank(actor);
        bool ok = true;
        try c.CashOut(balBefore) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = c.balances(actor);

        // General rule: a full-balance withdrawal must not both succeed AND leave
        // a positive balance behind. Reference: either ok==true and balAfter==0,
        // or ok==false and balAfter==balBefore. The bug's silent no-op makes
        // ok==false while balBefore>0, i.e. it pretends to have done nothing.
        assertTrue(
            (ok && balAfter == 0) || (!ok && balAfter == balBefore)
        );
    }
}
